questions.sparql:
SELECT ?o ?room ?area ?occupants WHERE {
  code:LoadFactorB twin:m2PerOccupant ?k . ?r twin:occupancy "B" ; twin:depictedBy ?o ; rdfs:label ?room .
  { SELECT ?o ?osx ?osy ?osz WHERE { ?o x3do:hasChildren ?oH . ?oH x3do:hasGeometry ?oB . ?oB x3do:size ?oS . ?oS rdf:first ?osx . ?oS rdf:rest ?oSR . ?oSR rdf:first ?osy . ?oSR rdf:rest ?oSR2 . ?oSR2 rdf:first ?osz . } }
  BIND(ROUND(?osx * ?osz) AS ?area) BIND(CEIL(?osx * ?osz / ?k) AS ?occupants)
} ORDER BY ?room

SELECT ?room (ROUND(MIN(?d)) AS ?metres) WHERE {
  ?r twin:occupancy "B" ; twin:depictedBy ?o ; rdfs:label ?room .
  ?ex a twin:Exit ; twin:status "open" ; twin:exitDoor/twin:depictedBy ?eo .
  { SELECT ?o ?ox ?oz WHERE { ?o x3do:translation ?oL . ?oL rdf:first ?ox . ?oL rdf:rest ?oR . ?oR rdf:rest ?oR2 . ?oR2 rdf:first ?oz . } } { SELECT ?eo ?eox ?eoz WHERE { ?eo x3do:translation ?eoL . ?eoL rdf:first ?eox . ?eoL rdf:rest ?eoR . ?eoR rdf:rest ?eoR2 . ?eoR2 rdf:first ?eoz . } }
  BIND(ABS(?ox - ?eox) + ABS(?oz - ?eoz) AS ?d)
} GROUP BY ?room ORDER BY ?room

SELECT ?o ?room (COUNT(DISTINCT ?door) AS ?doors) WHERE {
  code:LoadFactorB twin:m2PerOccupant ?k . code:TwoExits twin:maxOccupantsOneExit ?max .
  ?r twin:occupancy "B" ; twin:depictedBy ?o ; rdfs:label ?room . ?door bot:interfaceOf ?r ; twin:egress true .
  { SELECT ?o ?osx ?osy ?osz WHERE { ?o x3do:hasChildren ?oH . ?oH x3do:hasGeometry ?oB . ?oB x3do:size ?oS . ?oS rdf:first ?osx . ?oS rdf:rest ?oSR . ?oSR rdf:first ?osy . ?oSR rdf:rest ?oSR2 . ?oSR2 rdf:first ?osz . } }
  FILTER(?osx * ?osz / ?k > ?max)
} GROUP BY ?o ?room

inference.sparql:
SELECT DISTINCT ?o ?space WHERE {
  f:StairA (^bot:interfaceOf/bot:interfaceOf)+ ?s . ?s twin:depictedBy ?o ; rdfs:label ?space . FILTER(?s != f:StairA)
} ORDER BY ?space
